named :: String -> B.ByteString
named name = case [raw | (key, _, raw) <- cases, key == name] of
  [raw] -> raw
  _ -> error "fixed fixture missing or duplicated"

check :: (String, Bool, B.ByteString) -> (String, Bool)
check (name, expected, raw) = (name, isRight (W.decodeWorkspaceNavigation raw) == expected)

literalNavigation :: Bool
literalNavigation = case W.decodeWorkspaceNavigation (named "navigate-wide") of
  Left _ -> False
  Right value -> case W.navigationIntent value of
    Nothing -> False
    Just intent ->
      renderCounter (lifetime (W.navigationBinding value)) == "9007199254740993"
      && renderCounter (session (W.navigationBinding value)) == "9007199254740995"
      && renderCounter (frontend (W.navigationBinding value)) == "9007199254740997"
      && renderCounter (W.navigationRequest intent) == "18446744073709551615"
      && renderCounter (W.navigationGeneration intent) == "9007199254741007"
      && W.workspaceIdentity (W.navigationSource intent) == "1"
      && renderCounter (W.workspaceGeneration (W.navigationSource intent)) == "9007199254740999"
      && renderCounter (W.workspaceOutputGeneration (W.navigationSource intent)) == "9007199254741001"
      && W.workspaceIdentity (W.navigationDestination intent) == "9223372036854775807"
      && renderCounter (W.workspaceGeneration (W.navigationDestination intent)) == "18446744073709551615"
      && renderCounter (W.workspaceMonitor (W.navigationSource intent)) == "0"
      && renderCounter (W.workspaceMonitor (W.navigationDestination intent)) == "0"
      && renderCounter (W.workspaceOutputGeneration (W.navigationDestination intent)) == "9007199254741001"
      && renderCounter (contextLifetime (W.navigationContext intent)) == "9007199254740993"
      && renderCounter (contextOutput (W.navigationContext intent)) == "9007199254741003"
      && renderCounter (contextRevision (W.navigationContext intent)) == "9007199254741005"
      && renderCounter (contextEpoch (W.navigationContext intent)) == "9007199254740997"

literalRecovery :: Bool
literalRecovery = case W.decodeWorkspaceNavigation (named "recover-no-intent") of
  Left _ -> False
  Right value -> W.navigationIntent value == Nothing
    && renderCounter (lifetime (W.navigationBinding value)) == "9007199254740993"
    && renderCounter (session (W.navigationBinding value)) == "9007199254740995"
    && renderCounter (frontend (W.navigationBinding value)) == "9007199254740997"

padded :: Int -> B.ByteString
padded count = let raw = named "navigate-wide" in raw <> B.replicate (count - B.length raw) 32

commitWith :: B.ByteString -> B.ByteString
commitWith request = "{\"viewProtocol\":1,\"kind\":\"view-commit\",\"projection\":{},\"requests\":[" <> request <> "],\"focus\":[]}"

catalog :: B.ByteString
catalog = "{\"protocolVersion\":3,\"kind\":\"catalog-request\",\"binding\":{\"lifetime\":\"1\",\"session\":\"2\",\"frontend\":\"3\"},\"requestId\":\"1\"}"

replaceIdentityWith :: B.ByteString -> B.ByteString
replaceIdentityWith replacement =
  let raw = named "navigate-wide"
      needle = "\"identity\":\"1\""
      (front, rest) = C.breakSubstring needle raw
  in front <> "\"identity\":\"" <> replacement <> "\"" <> B.drop (B.length needle) rest

additionalChecks :: [(String, Bool)]
additionalChecks =
  let nav = named "navigate-wide"
      rec = named "recover-no-intent"
      raw8191 = padded 8191
      raw8192 = padded 8192
      raw8193 = padded 8193
      raw131072 = padded 131072
      raw131073 = padded 131073
      renderWithExtra n =
        let prefix = B.init nav <> ",\"padding\":\""
            suffix = "\"}"
        in prefix <> B.replicate (n - B.length prefix - B.length suffix) 97 <> suffix
      rendered8192 = renderWithExtra 8192
      rendered8193 = renderWithExtra 8193
      paddedCatalog = catalog <> B.replicate (8193 - B.length catalog) 32
      acceptedThenRefused = isRight (W.decodeWorkspaceNavigation nav) && isLeft (W.decodeWorkspaceNavigation "{")
      refusedThenAccepted = isLeft (W.decodeWorkspaceNavigation "{") && isRight (W.decodeWorkspaceNavigation rec)
      unicodeNonDigit = replaceIdentityWith (B.pack [0xc3, 0xa9])
      invalidUtf8 = replaceIdentityWith (B.pack [0xff])
      unicodeMetric = let text = T.singleton '\x1f600' in B.length (TE.encodeUtf8 text)==4 && utf16Length text==2
      extras =
        [ ("literal-navigation-values", literalNavigation)
        , ("literal-recovery-no-request", literalRecovery)
        , ("candidate-preserves-raw-wire", (W.decodeWorkspaceNavigation raw8192 >>= W.encodeWorkspaceNavigation) == Right raw8192)
        , ("raw-8191-accepted", B.length raw8191 == 8191 && isRight (W.decodeWorkspaceNavigation raw8191))
        , ("raw-8192-accepted", B.length raw8192 == 8192 && isRight (W.decodeWorkspaceNavigation raw8192))
        , ("raw-8193-whitespace-accepted", B.length raw8193 == 8193 && isRight (W.decodeWorkspaceNavigation raw8193))
        , ("raw-131072-whitespace-accepted", B.length raw131072 == 131072 && isRight (W.decodeWorkspaceNavigation raw131072))
        , ("raw-131073-refused", B.length raw131073 == 131073 && isLeft (W.decodeWorkspaceNavigation raw131073))
        , ("rendered-8192-invalid-extra-field", B.length rendered8192 == 8192 && isLeft (W.decodeWorkspaceNavigation rendered8192))
        , ("rendered-8193-limit-precedes-schema", B.length rendered8193 == 8193 && W.decodeWorkspaceNavigation rendered8193 == Left "navigation rendered request capacity")
        , ("desktop-rendered-catalog-ignores-request-whitespace", B.length paddedCatalog == 8193 && isRight (D.decodeDesktopCommit (commitWith paddedCatalog)))
        , ("desktop-remains-failclosed-navigation", isLeft (D.decodeDesktopCommit (commitWith nav)))
        , ("desktop-remains-failclosed-recover", isLeft (D.decodeDesktopCommit (commitWith rec)))
        , ("unicode-nondigit-refused", isLeft (W.decodeWorkspaceNavigation unicodeNonDigit))
        , ("invalid-utf8-refused", isLeft (W.decodeWorkspaceNavigation invalidUtf8))
        , ("supplementary-utf8-vs-utf16", unicodeMetric)
        , ("accepted-then-refused-independent-decodes", acceptedThenRefused)
        , ("refused-then-accepted-independent-decodes", refusedThenAccepted)
        ]
  in map (\(name, ok) -> ("independent/" ++ name, ok)) (map check cases ++ extras)
